css:
.qk-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.qk-stage canvas { touch-action: none; cursor: crosshair; }
.qk-out { margin: 0; font-size: 21px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 2.2em; }
.qk-table { width: 100%; border-collapse: collapse; font-size: 18px; }
.qk-table th, .qk-table td { border: 1.5px solid var(--rule); padding: 3px 8px; text-align: left; }
.qk-table th { background: #eef2f7; white-space: nowrap; }

